const fs = require\('fs'\);
const path = require\('path'\);

const filePath = path.join\('packages', 'opencode', 'src', 'session', 'index.ts'\);
let content = fs.readFileSync\(filePath, 'utf-8'\);

// The new get function - simplified to match the task requirements
const newGet = `  export const get = fn\(Identifier.schema\("session"\), async \(id\) => {
    // Use getSessionStoragePath for user-isolated storage
    const { getCurrentUserId, getSessionStoragePath } = await import\("../server/middleware/user-context"\)
    const userId = getCurrentUserId\(\)
    const sessionPath = getSessionStoragePath\(userId, id\)

    try {
      const data = await Storage.read<Info>\(sessionPath\)
      return data
    } catch {
      // Return null for non-existent sessions
      return null
    }
  }\)`;

// Find and replace the get function
const getRegex = /export const get = fn\\\(Identifier\\.schema\\\("session"\\\), async \\\(id\\\) => \\{[\\s\\S]*?export const getShare/;
content = content.replace\(getRegex, newGet + '\\n\\n  export const getShare'\);

// The new remove function - simplified to use getSessionStoragePath
const newRemove = `  export const remove = fn\(Identifier.schema\("session"\), async \(sessionID\) => {
    // Use getSessionStoragePath for user-isolated storage
    const { getCurrentUserId, getSessionStoragePath } = await import\("../server/middleware/user-context"\)
    const userId = getCurrentUserId\(\)
    const sessionPath = getSessionStoragePath\(userId, sessionID\)

    try {
      const session = await get\(sessionID\)

      // Cancel any pending container retries for this session
      const { cancelContainerRetry } = await import\("./docker"\)
      cancelContainerRetry\(sessionID\)

      // Note: User container is NOT destroyed when session is removed
      // It persists across sessions and is managed by UserContainerManager

      for \(const child of await children\(sessionID\)\) {
        await remove\(child.id\)
      }
      await unshare\(sessionID\).catch\(\(\) => {}\)
      for \(const msg of await Storage.list\(["message", sessionID]\)\) {
        for \(const part of await Storage.list\(["part", msg.at\(-1\)!]\)\) {
          await Storage.remove\(part\)
        }
        await Storage.remove\(msg\)
      }
      await Storage.remove\(sessionPath\)
      Bus.publish\(Event.Deleted, {
        info: session,
      }\)
    } catch \(e: any\) {
      log.error\("Failed to remove session", { sessionID, error: e.message, stack: e.stack }\)
      throw new Error\(`Failed to delete session ${sessionID}: ${e.message}`\)
    }
  }\)`;

// Find and replace the remove function
const removeRegex = /export const remove = fn\\\(Identifier\\.schema\\\("session"\\\), async \\\(sessionID\\\) => \\{[\\s\\S]*?export const updateMessage/;
content = content.replace\(removeRegex, newRemove + '\\n\\n  export const updateMessage'\);

fs.writeFileSync\(filePath, content, 'utf-8'\);
console.log\('File updated successfully'\);
console.log\('get function:', newGet.substring\(0, 100\) + '...'\);
console.log\('remove function:', newRemove.substring\(0, 100\) + '...'\);
ENDOFFILE)
